package com.creatorhub.servlet; import com.creatorhub.dao.CreatorDAO; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import javax.servlet.*; import java.io.*; @WebServlet("/dashboard") public class DashboardServlet extends HttpServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{if(!ok(r)){s.sendRedirect(r.getContextPath()+"/?error=Login+required");return;}try{int id=(Integer)r.getSession().getAttribute("studentId");CreatorDAO d=new CreatorDAO();r.setAttribute("collaborations",d.myCollaborations(id));r.setAttribute("applications",d.applications(id));r.getRequestDispatcher("/WEB-INF/jsp/dashboard.jsp").forward(r,s);}catch(Exception e){throw new ServletException(e);}}private boolean ok(HttpServletRequest r){return r.getSession(false)!=null&&r.getSession(false).getAttribute("studentId")!=null;}}
